class Runnable:
    def __or__(self, other):
        return RunnableSequence(self, other)

    def invoke(self, value):
        raise NotImplementedError


class RunnableSequence(Runnable):
    def __init__(self, *steps):
        self.steps = steps

    def invoke(self, value):
        for step in self.steps:
            value = step.invoke(value)
        return value


class ChatPromptTemplate(Runnable):
    def __init__(self, messages):
        self.messages = messages

    @classmethod
    def from_messages(cls, messages):
        return cls(messages)

    def invoke(self, variables):
        return [(role, text.format(**variables)) for role, text in self.messages]


class ChatOpenAI(Runnable):
    """Offline stand-in for the chat model (no network in the sandbox)."""

    def __init__(self, model, temperature=0.7):
        self.model = model
        self.temperature = temperature

    def invoke(self, messages):
        human = [text for role, text in messages if role == "human"][-1]
        level = human.split()[1]
        language = human.split("for the ")[1].split(" programming")[0]
        return {"content": f"(A practice exercise for {language} {level}s)"}


class StrOutputParser(Runnable):
    def invoke(self, message):
        return message["content"]


# Create prompt template with {language} and {level}
prompt = ChatPromptTemplate.from_messages([
    ("system", "You are a programming instructor who writes concise practice exercises."),
    ("human", "Create {level} level practice exercise for the {language} programming language."),
])

model = ChatOpenAI(model='gpt-4o-mini', temperature=0.7)

# Build the chain
chain = prompt | model | StrOutputParser()

# Invoke with language='Python' and level='beginner'
result = chain.invoke({'language': 'Python', 'level': 'beginner'})
print(result)
